// ===== eingebettet aus src/fehlerklassen.js – nicht hier bearbeiten, sondern im Repo (npm run build) =====
const fehlerklassen = (() => {
const module = { exports: {} };
// Fehlerklassen und Statuscode-Mapping (Masterprompt 3, Bauplan 3).
// EPA-Fehler werden als Text "[EPA:<status>:<CODE>:<Vorgangs-ID|->] <Meldung>" geworfen,
// damit der Error-Handler (EPA-05) sie aus execution.error.message zurücklesen kann.

const FEHLERCODES = Object.freeze({
	UNGUELTIGES_FORMAT: { status: 400, klasse: 'Eingabe', retrybar: false },
	UNGUELTIGER_AUSLOESER: { status: 400, klasse: 'Eingabe', retrybar: false },
	UNBEKANNTER_STATUS: { status: 400, klasse: 'Eingabe', retrybar: false },
	AUTH_FEHLER: { status: 401, klasse: 'Authentifizierung', retrybar: false },
	KEINE_BERECHTIGUNG: { status: 403, klasse: 'Authentifizierung', retrybar: false },
	VORGANG_NICHT_GEFUNDEN: { status: 404, klasse: 'Nicht gefunden', retrybar: false },
	KONFIG_NICHT_GEFUNDEN: { status: 404, klasse: 'Konfiguration', retrybar: false },
	NICHT_GEFUNDEN: { status: 404, klasse: 'Nicht gefunden', retrybar: false },
	DUPLIKAT: { status: 409, klasse: 'Konflikt', retrybar: false },
	UNZULAESSIGER_STATUSWECHSEL: { status: 409, klasse: 'Konflikt', retrybar: false },
	UNZULAESSIGER_AUSLOESER: { status: 409, klasse: 'Konflikt', retrybar: false },
	VERSIONSKONFLIKT: { status: 409, klasse: 'Konflikt', retrybar: true },
	GESPERRT: { status: 409, klasse: 'Konflikt', retrybar: true },
	KONFIG_MEHRDEUTIG: { status: 409, klasse: 'Konfiguration', retrybar: false },
	FREIGABE_ABGELAUFEN: { status: 410, klasse: 'Freigabe', retrybar: false },
	EXTRAKTION_UNGUELTIG: { status: 422, klasse: 'LLM', retrybar: false },
	KONFIGURATIONSFEHLER: { status: 424, klasse: 'Konfiguration', retrybar: false },
	RATE_LIMIT: { status: 429, klasse: 'Upstream', retrybar: true },
	UPSTREAM_FEHLER: { status: 502, klasse: 'Upstream', retrybar: true },
	NICHT_ERREICHBAR: { status: 503, klasse: 'Upstream', retrybar: true },
	ZEITUEBERSCHREITUNG: { status: 504, klasse: 'Upstream', retrybar: true },
	UNBEKANNT: { status: 500, klasse: 'Unbekannt', retrybar: false },
});

// Bei diesen Codes bearbeitet eine andere Ausführung den Vorgang bzw. die Mail ist schon verarbeitet:
// der Vorgang wird NICHT auf "Eskaliert / Manuell" gesetzt (sonst würde ein Parallellauf gestört).
const OHNE_ESKALATION = Object.freeze(['VERSIONSKONFLIKT', 'GESPERRT', 'DUPLIKAT']);

const EPA_MUSTER = /^\[EPA:(\d{3}):([A-Z_]+):([^\]]*)\]\s*([\s\S]*)$/;

function formatEpaFehler(code, vorgangsId, meldung) {
	const def = FEHLERCODES[code] || FEHLERCODES.UNBEKANNT;
	return `[EPA:${def.status}:${FEHLERCODES[code] ? code : 'UNBEKANNT'}:${vorgangsId || '-'}] ${meldung || ''}`.trim();
}

/** Wirft einen EPA-Fehler (für Code-Nodes). */
function epaFehler(code, vorgangsId, meldung) {
	const err = new Error(formatEpaFehler(code, vorgangsId, meldung));
	err.epaCode = code;
	return err;
}

function parseEpaFehler(text) {
	if (typeof text !== 'string') return null;
	// n8n stellt der Meldung manchmal Präfixe voran; das Muster darf irgendwo in der ersten Zeile beginnen.
	const start = text.indexOf('[EPA:');
	if (start < 0) return null;
	const m = text.slice(start).match(EPA_MUSTER);
	if (!m) return null;
	return {
		status: Number(m[1]),
		code: m[2],
		vorgangsId: m[3] === '-' ? null : m[3],
		meldung: m[4].trim(),
	};
}

/** Entfernt personenbezogene Daten und kürzt (keine Mail-Inhalte im Fehlerlog). */
function bereinigeMeldung(text, maxLaenge = 300) {
	if (text === undefined || text === null) return '';
	let s = String(text)
		.replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '<email>')
		.replace(/\+?\d[\d\s/().-]{7,}\d/g, '<nummer>')
		.replace(/Bearer\s+[A-Za-z0-9._~+/=-]+/g, 'Bearer <token>')
		.replace(/\s+/g, ' ')
		.trim();
	if (s.length > maxLaenge) s = s.slice(0, maxLaenge - 1) + '…';
	return s;
}

function codeAusHttpStatus(status) {
	const n = Number(status);
	if (!Number.isFinite(n)) return null;
	if (n === 400 || n === 422) return 'UNGUELTIGES_FORMAT';
	if (n === 401) return 'AUTH_FEHLER';
	if (n === 403) return 'KEINE_BERECHTIGUNG';
	if (n === 404) return 'NICHT_GEFUNDEN';
	if (n === 408 || n === 504) return 'ZEITUEBERSCHREITUNG';
	if (n === 409) return 'DUPLIKAT';
	if (n === 429) return 'RATE_LIMIT';
	if (n === 503) return 'NICHT_ERREICHBAR';
	if (n >= 500 && n < 600) return 'UPSTREAM_FEHLER';
	return null;
}

function codeAusText(text) {
	const t = String(text || '');
	if (/timed? ?out|ETIMEDOUT|ESOCKETTIMEDOUT|timeout of \d+ms/i.test(t)) return 'ZEITUEBERSCHREITUNG';
	if (/ECONNREFUSED|ECONNRESET|ENOTFOUND|EAI_AGAIN|socket hang up|service unavailable/i.test(t)) return 'NICHT_ERREICHBAR';
	if (/rate.?limit|too many requests/i.test(t)) return 'RATE_LIMIT';
	if (/invalid_grant|unauthori[sz]ed|token (has )?expired|invalid.?token|authentication failed|password authentication/i.test(t)) return 'AUTH_FEHLER';
	if (/forbidden|insufficient privileges|access denied|permission denied/i.test(t)) return 'KEINE_BERECHTIGUNG';
	if (/duplicate key|unique constraint/i.test(t)) return 'DUPLIKAT';
	return null;
}

/**
 * Klassifiziert einen Fehler.
 * @param {{message?: string, description?: string, httpCode?: string|number}} fehler
 */
function klassifiziereFehler(fehler) {
	const f = fehler || {};
	const epa = parseEpaFehler(f.message) || parseEpaFehler(f.description);
	let code;
	let vorgangsId = null;
	let meldung;
	if (epa) {
		code = FEHLERCODES[epa.code] ? epa.code : 'UNBEKANNT';
		vorgangsId = epa.vorgangsId;
		meldung = epa.meldung;
	} else {
		code = codeAusHttpStatus(f.httpCode) || codeAusText(`${f.message || ''} ${f.description || ''}`) || 'UNBEKANNT';
		meldung = f.message || f.description || '';
	}
	const def = FEHLERCODES[code];
	return {
		statuscode: def.status,
		fehlercode: code,
		klasse: def.klasse,
		retrybar: def.retrybar,
		eskalieren: !OHNE_ESKALATION.includes(code),
		vorgangsId,
		meldung: bereinigeMeldung(meldung),
	};
}

/**
 * Baut aus der Ausgabe des Error Trigger einen Fehlerlog-Eintrag (ohne Mail-Inhalte).
 * Error Trigger liefert entweder {execution, workflow} oder bei Trigger-Fehlern {trigger, workflow}.
 */
function ausErrorTrigger(json) {
	const j = json || {};
	const exec = j.execution || {};
	const err = exec.error || (j.trigger && j.trigger.error) || {};
	const k = klassifiziereFehler({
		message: err.message,
		description: err.description,
		httpCode: err.httpCode,
	});
	const node = (err.node && err.node.name) || exec.lastNodeExecuted || null;
	const workflow = j.workflow || {};
	return {
		statuscode: k.statuscode,
		fehlercode: k.fehlercode,
		klasse: k.klasse,
		retrybar: k.retrybar,
		eskalieren: k.eskalieren && Boolean(k.vorgangsId),
		workflow_id: workflow.id || null,
		workflow_name: workflow.name || null,
		node,
		execution_id: exec.id !== undefined && exec.id !== null ? String(exec.id) : null,
		execution_url: exec.url || null,
		modus: exec.mode || (j.trigger && j.trigger.mode) || null,
		vorgangs_id: k.vorgangsId,
		meldung: k.meldung,
	};
}

function escapeHtml(s) {
	return String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
}

function alarmHtml(eintrag) {
	const e = eintrag;
	const zeilen = [
		`<b>EPA-Fehler ${e.statuscode} ${escapeHtml(e.fehlercode)}</b> (${escapeHtml(e.klasse)})`,
		`Workflow: ${escapeHtml(e.workflow_name || e.workflow_id || '?')}`,
		`Node: ${escapeHtml(e.node || '?')}`,
		`Vorgang: ${escapeHtml(e.vorgangs_id || '–')}`,
		`Meldung: ${escapeHtml(e.meldung || '–')}`,
		e.retrybar ? 'Hinweis: vorübergehender Fehler, erneuter Versuch kann helfen.' : 'Hinweis: dauerhafter Fehler, bitte prüfen.',
	];
	if (e.execution_url) zeilen.push(`<a href="${escapeHtml(e.execution_url)}">Ausführung ${escapeHtml(e.execution_id)} öffnen</a>`);
	return zeilen.join('<br>');
}

module.exports = {
	FEHLERCODES,
	OHNE_ESKALATION,
	formatEpaFehler,
	epaFehler,
	parseEpaFehler,
	bereinigeMeldung,
	klassifiziereFehler,
	ausErrorTrigger,
	alarmHtml,
	escapeHtml,
};
return module.exports;
})();
// ===== Ende src/fehlerklassen.js =====
// ===== eingebettet aus src/entwurf.js – nicht hier bearbeiten, sondern im Repo (npm run build) =====
const entwurf = (() => {
const module = { exports: {} };
// Rückfrage-Entwurf (Masterprompt C1, C2; Bauplan 5.5).
// Das LLM liefert nur die Hülle (Anrede, Einleitung, Schluss) als getrennte Felder. Die festen Textbausteine,
// die Signatur und der KI-Hinweis werden hier deterministisch eingesetzt. Damit stehen die Bausteine
// konstruktionsbedingt wortgleich in der Mail. Die Hülle wird geprüft; bei Verstoß gilt das Template-Gerüst (Fallback).

const MAX = Object.freeze({ anrede: 80, einleitung: 400, schluss: 300, gesamt: 600 });

// Zusage- und Fakten-Wörter, die in der Hülle nichts verloren haben (Wortanfänge, klein).
const VERBOTEN = Object.freeze([
	'garantier', 'zusag', 'zusich', 'verbindlich', 'kostenlos', 'gratis', 'preis', 'rabatt', 'euro', 'versprech',
	'spätestens', 'innerhalb von', 'bis zum', 'sofort', 'umgehend', 'bestätigen wir', 'guarantee', 'free of charge', 'price', 'discount',
]);

function normalisiereLeerraum(s) {
	return String(s ?? '').replace(/\s+/g, ' ').trim();
}

/** Anzeigename des Kunden für die Anrede: nur Buchstaben, Leerzeichen, Bindestrich, Punkt; sonst leer. */
function sichererName(name) {
	const n = normalisiereLeerraum(name).replace(/^["']|["']$/g, '');
	if (!n || n.length > 60 || n.includes('@')) return '';
	return /^[\p{L}][\p{L} .'-]*$/u.test(n) ? n : '';
}

/** Feste Bausteine der fehlenden Felder in Config-Reihenfolge. Fehlender Baustein = Konfigurationsfehler. */
function bausteine(fehlende, felder) {
	const nachName = new Map((felder || []).map((f) => [f.feldname, f]));
	const fehlendeNamen = new Set((fehlende || []).map((f) => f.feldname));
	const out = [];
	for (const f of felder || []) {
		if (!fehlendeNamen.has(f.feldname)) continue;
		const b = normalisiereLeerraum(f.resolution_textbaustein);
		if (!b) throw new Error(`Textbaustein für Feld "${f.feldname}" fehlt`);
		out.push({ feldname: f.feldname, anzeigename: f.anzeigename, text: b });
	}
	for (const n of fehlendeNamen) if (!nachName.has(n)) throw new Error(`Feld "${n}" ist in der Config unbekannt`);
	return out;
}

/** Template-Gerüst ohne LLM (Fallback). */
function vorlage({ anrede_stil: stil, sprache }, name) {
	const n = sichererName(name);
	if (sprache === 'en') {
		return {
			anrede: n ? `Dear ${n},` : 'Hello,',
			einleitung: 'Thank you for your request. To process it, we still need the following information:',
			schluss: 'Thank you in advance for your reply.',
		};
	}
	if (stil === 'Du') {
		return {
			anrede: n ? `Hallo ${n},` : 'Hallo,',
			einleitung: 'vielen Dank für deine Anfrage. Damit wir sie bearbeiten können, brauchen wir noch folgende Angaben:',
			schluss: 'Vielen Dank für deine Rückmeldung.',
		};
	}
	return {
		anrede: n ? `Guten Tag ${n},` : 'Guten Tag,',
		einleitung: 'vielen Dank für Ihre Anfrage. Damit wir sie bearbeiten können, benötigen wir noch folgende Angaben:',
		schluss: 'Vielen Dank für Ihre Rückmeldung.',
	};
}

/** Template für die Erinnerung an den Kunden (Phase E, Fall 1). Bewusst ohne LLM: deterministisch und prüfbar. */
function vorlageErinnerung({ anrede_stil: stil, sprache }, name) {
	const n = sichererName(name);
	if (sprache === 'en') {
		return {
			anrede: n ? `Dear ${n},` : 'Hello,',
			einleitung: 'we would like to kindly remind you of our previous message. To process your request, we still need the following information:',
			schluss: 'Thank you in advance for your reply.',
		};
	}
	if (stil === 'Du') {
		return {
			anrede: n ? `Hallo ${n},` : 'Hallo,',
			einleitung: 'wir möchten dich freundlich an unsere letzte Nachricht erinnern. Damit wir deine Anfrage bearbeiten können, brauchen wir noch folgende Angaben:',
			schluss: 'Vielen Dank für deine Rückmeldung.',
		};
	}
	return {
		anrede: n ? `Guten Tag ${n},` : 'Guten Tag,',
		einleitung: 'wir möchten Sie freundlich an unsere letzte Nachricht erinnern. Damit wir Ihre Anfrage bearbeiten können, benötigen wir noch folgende Angaben:',
		schluss: 'Vielen Dank für Ihre Rückmeldung.',
	};
}

/**
 * Prüft die vom LLM gelieferte Hülle. Gibt eine Liste von Verstößen zurück (leer = in Ordnung).
 * Name des Kunden darf in der Anrede stehen, sonst keine Ziffern, Beträge, URLs, Adressen, Zusagen.
 */
function huellePruefen(huelle, { anrede_stil: stil } = {}) {
	const fehler = [];
	if (!huelle || typeof huelle !== 'object') return ['keine Hülle'];
	let gesamt = 0;
	for (const teil of ['anrede', 'einleitung', 'schluss']) {
		const t = normalisiereLeerraum(huelle[teil]);
		gesamt += t.length;
		if (!t) fehler.push(`${teil}: leer`);
		if (t.length > MAX[teil]) fehler.push(`${teil}: zu lang`);
		if (/\d/.test(t)) fehler.push(`${teil}: enthält Ziffern`);
		if (/[€$£]|\b(eur|usd|chf)\b/i.test(t)) fehler.push(`${teil}: enthält Währung`);
		if (/(https?:\/\/|www\.|\b[a-z0-9-]+\.(de|com|net|org|eu|io)\b)/i.test(t)) fehler.push(`${teil}: enthält Link`);
		if (/@/.test(t)) fehler.push(`${teil}: enthält E-Mail-Adresse`);
		if (/[{}[\]<>]/.test(t)) fehler.push(`${teil}: enthält Platzhalter oder Markup`);
		const klein = t.toLowerCase();
		for (const w of VERBOTEN) if (klein.includes(w)) fehler.push(`${teil}: verbotenes Wort "${w}"`);
		if (stil === 'Sie' && /\b(du|dich|dir|dein|deine|deinen|deinem|deiner|euch|euer)\b/i.test(t)) fehler.push(`${teil}: duzt statt siezt`);
		if (stil === 'Sie' && /(^|[.!?]\s+|\s)ihr\b/.test(t)) fehler.push(`${teil}: duzt statt siezt`);
	}
	if (gesamt > MAX.gesamt) fehler.push('Hülle insgesamt zu lang');
	return [...new Set(fehler)];
}

function esc(s) {
	return String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
}

/** Editierbarer Teil als Text (für Vorschau und Bearbeiten-Formular). */
function bearbeitbarerText(huelle, bs) {
	return [normalisiereLeerraum(huelle.anrede), '', normalisiereLeerraum(huelle.einleitung), '', ...bs.map((b) => `- ${b.text}`), '', normalisiereLeerraum(huelle.schluss)].join('\n');
}

/** Fester Abschluss: Signatur und KI-Hinweis (nie vom LLM, nie im Formular änderbar). */
function abschlussText(config) {
	return [String(config.signatur || '').trim(), '', '--', String(config.ki_hinweistext || '').trim()].join('\n');
}

/** Text (bearbeitbarer Teil) -> HTML-Mail mit festem Abschluss. Text wird vollständig escaped. */
function zuHtml(text, config) {
	const absatz = (t) => esc(t).replace(/\r\n?/g, '\n').replace(/\n/g, '<br>');
	return `<div style="font-family:Arial,sans-serif;font-size:11pt">${absatz(text)}<br><br>${absatz(String(config.signatur || '').trim())}<br><br><span style="color:#666;font-size:9pt">${esc(String(config.ki_hinweistext || '').trim())}</span></div>`;
}

/**
 * Setzt den Entwurf zusammen.
 * @param {object|null} llmHuelle { anrede, einleitung, schluss } oder null (LLM fehlgeschlagen)
 * @returns {{ text, html, abschluss, bausteine, fallback, pruefung }}
 */
function entwurfBauen(llmHuelle, { config, felder, fehlende, name }) {
	const bs = bausteine(fehlende, felder);
	if (!bs.length) throw new Error('Keine fehlenden Felder: keine Rückfrage nötig');
	const pruefung = llmHuelle ? huellePruefen(llmHuelle, config) : ['LLM-Entwurf nicht verfügbar'];
	const fallback = pruefung.length > 0;
	const huelle = fallback ? vorlage(config, name) : llmHuelle;
	const text = bearbeitbarerText(huelle, bs);
	return { text, html: zuHtml(text, config), abschluss: abschlussText(config), bausteine: bs, fallback, pruefung };
}

/** Erinnerungs-Entwurf: Template-Hülle, feste Bausteine der noch offenen Felder, fester Abschluss. */
function erinnerungBauen({ config, felder, fehlende, name }) {
	const bs = bausteine(fehlende, felder);
	if (!bs.length) throw new Error('Keine fehlenden Felder: keine Erinnerung nötig');
	const text = bearbeitbarerText(vorlageErinnerung(config, name), bs);
	return { text, html: zuHtml(text, config), abschluss: abschlussText(config), bausteine: bs, fallback: false, pruefung: [] };
}

/**
 * Prüft einen vom Mitarbeiter bearbeiteten Text. Er darf frei formulieren; abgelehnt werden nur leere oder
 * übermäßig lange Texte. Fehlende Bausteine werden als Hinweis gemeldet (der Mitarbeiter verantwortet die Änderung).
 */
function bearbeitungPruefen(text, bs) {
	const t = String(text ?? '').replace(/\r\n?/g, '\n').trim();
	if (!t) return { ok: false, grund: 'Der Text ist leer.' };
	if (t.length > 5000) return { ok: false, grund: 'Der Text ist zu lang (max. 5000 Zeichen).' };
	const norm = normalisiereLeerraum(t);
	const fehlend = (bs || []).filter((b) => !norm.includes(b.text)).map((b) => b.anzeigename);
	return { ok: true, text: t, bausteine_entfernt: fehlend };
}

module.exports = { MAX, VERBOTEN, sichererName, bausteine, vorlage, vorlageErinnerung, erinnerungBauen, huellePruefen, bearbeitbarerText, abschlussText, zuHtml, entwurfBauen, bearbeitungPruefen, esc };
return module.exports;
})();
// ===== Ende src/entwurf.js =====

// ----- Node-Logik -----
const e = $('Bei Aufruf').first().json;
const config = $('Config laden').first().json.config;
const v = $input.first().json.vorgang;
const fehler = (code, text) => fehlerklassen.epaFehler(code, v.vorgangs_id, text);
const art = e.art || 'rueckfrage';
if (!['rueckfrage', 'erinnerung'].includes(art)) throw fehler('UNGUELTIGES_FORMAT', `Unbekannte Art "${art}"`);
const statusSoll = art === 'erinnerung' ? 'Warten auf Kunde' : 'Lücken erkannt';
if (v.status !== statusSoll) throw fehler('UNZULAESSIGER_STATUSWECHSEL', `${art === 'erinnerung' ? 'Erinnerung' : 'Rückfrage'} nur im Status "${statusSoll}" (ist "${v.status}")`);
if (!config.postfach_workflow_id) throw fehler('KONFIGURATIONSFEHLER', 'postfach_workflow_id fehlt in der Config (ID der EPA-00-Kopie für dieses Postfach)');
if (!config.freigeber.length) throw fehler('KONFIGURATIONSFEHLER', 'Keine Freigeber konfiguriert');
const felder = config.vorgangstypen[v.vorgangstyp];
if (!felder) throw fehler('KONFIGURATIONSFEHLER', `Vorgangstyp "${v.vorgangstyp}" fehlt in der Config`);
const fehlende = (v.fehlende_felder || []).filter((f) => f && f.feldname);
if (!fehlende.length) throw fehler('UNGUELTIGES_FORMAT', 'Keine fehlenden Felder vermerkt');
let bs;
try { bs = entwurf.bausteine(fehlende, felder); } catch (err) { throw fehler('KONFIGURATIONSFEHLER', err.message); }
// Erinnerung: gleiche Runde (die Rückfrage dieser Runde ist schon gesendet); der Rundenzähler steigt nicht.
const runde = Number(v.rundenzaehler || 0) + (art === 'erinnerung' ? 0 : 1);
const max = Number(config.max_runden);
return [{ json: {
	weg: art === 'erinnerung' ? 'vorlage' : runde > max ? 'eskalieren' : 'entwurf',
	art,
	ausloeser: art === 'erinnerung' ? 'Cronjob' : 'System',
	erinnerung_nr: Number(v.erinnerungen_gesendet || 0) + 1,
	runde,
	max_runden: max,
	fehlende,
	name: entwurf.sichererName(v.absender_name),
	kontext: { anrede_stil: config.anrede_stil, sprache: config.sprache, name: entwurf.sichererName(v.absender_name), betreff: v.betreff || '', luecken: bs.map((b) => b.anzeigename), runde },
} }];

// ===== eingebettet aus src/entwurf.js – nicht hier bearbeiten, sondern im Repo (npm run build) =====
const entwurf = (() => {
const module = { exports: {} };
// Rückfrage-Entwurf (Masterprompt C1, C2; Bauplan 5.5).
// Das LLM liefert nur die Hülle (Anrede, Einleitung, Schluss) als getrennte Felder. Die festen Textbausteine,
// die Signatur und der KI-Hinweis werden hier deterministisch eingesetzt. Damit stehen die Bausteine
// konstruktionsbedingt wortgleich in der Mail. Die Hülle wird geprüft; bei Verstoß gilt das Template-Gerüst (Fallback).

const MAX = Object.freeze({ anrede: 80, einleitung: 400, schluss: 300, gesamt: 600 });

// Zusage- und Fakten-Wörter, die in der Hülle nichts verloren haben (Wortanfänge, klein).
const VERBOTEN = Object.freeze([
	'garantier', 'zusag', 'zusich', 'verbindlich', 'kostenlos', 'gratis', 'preis', 'rabatt', 'euro', 'versprech',
	'spätestens', 'innerhalb von', 'bis zum', 'sofort', 'umgehend', 'bestätigen wir', 'guarantee', 'free of charge', 'price', 'discount',
]);

function normalisiereLeerraum(s) {
	return String(s ?? '').replace(/\s+/g, ' ').trim();
}

/** Anzeigename des Kunden für die Anrede: nur Buchstaben, Leerzeichen, Bindestrich, Punkt; sonst leer. */
function sichererName(name) {
	const n = normalisiereLeerraum(name).replace(/^["']|["']$/g, '');
	if (!n || n.length > 60 || n.includes('@')) return '';
	return /^[\p{L}][\p{L} .'-]*$/u.test(n) ? n : '';
}

/** Feste Bausteine der fehlenden Felder in Config-Reihenfolge. Fehlender Baustein = Konfigurationsfehler. */
function bausteine(fehlende, felder) {
	const nachName = new Map((felder || []).map((f) => [f.feldname, f]));
	const fehlendeNamen = new Set((fehlende || []).map((f) => f.feldname));
	const out = [];
	for (const f of felder || []) {
		if (!fehlendeNamen.has(f.feldname)) continue;
		const b = normalisiereLeerraum(f.resolution_textbaustein);
		if (!b) throw new Error(`Textbaustein für Feld "${f.feldname}" fehlt`);
		out.push({ feldname: f.feldname, anzeigename: f.anzeigename, text: b });
	}
	for (const n of fehlendeNamen) if (!nachName.has(n)) throw new Error(`Feld "${n}" ist in der Config unbekannt`);
	return out;
}

/** Template-Gerüst ohne LLM (Fallback). */
function vorlage({ anrede_stil: stil, sprache }, name) {
	const n = sichererName(name);
	if (sprache === 'en') {
		return {
			anrede: n ? `Dear ${n},` : 'Hello,',
			einleitung: 'Thank you for your request. To process it, we still need the following information:',
			schluss: 'Thank you in advance for your reply.',
		};
	}
	if (stil === 'Du') {
		return {
			anrede: n ? `Hallo ${n},` : 'Hallo,',
			einleitung: 'vielen Dank für deine Anfrage. Damit wir sie bearbeiten können, brauchen wir noch folgende Angaben:',
			schluss: 'Vielen Dank für deine Rückmeldung.',
		};
	}
	return {
		anrede: n ? `Guten Tag ${n},` : 'Guten Tag,',
		einleitung: 'vielen Dank für Ihre Anfrage. Damit wir sie bearbeiten können, benötigen wir noch folgende Angaben:',
		schluss: 'Vielen Dank für Ihre Rückmeldung.',
	};
}

/** Template für die Erinnerung an den Kunden (Phase E, Fall 1). Bewusst ohne LLM: deterministisch und prüfbar. */
function vorlageErinnerung({ anrede_stil: stil, sprache }, name) {
