return [{ json: { ergebnis: 'freigabe_angefordert', art: $('Rückfrage vorbereiten').first().json.art, freigabe_id: z.freigabe_id, zugestellt: $('Zustellung auswerten').first().json.zugestellt, fallback: z.fallback } }];
